    fun category(scalar: Int): Int {
        val index = rangeIndex(categories, 3, scalar)
        return if (index < 0) ANY else categories[index + 2]
    }

    fun isInCbExtend(scalar: Int): Boolean = rangeIndex(incbExtends, 2, scalar) >= 0

    fun isInCbLinker(scalar: Int): Boolean = when (scalar) { 0x94D, 0x9CD, 0xACD, 0xB4D, 0xC4D, 0xD4D -> true; else -> false }

    private fun rangeIndex(table: IntArray, stride: Int, scalar: Int): Int {
        var low = 0
        var high = table.size / stride - 1
        while (low <= high) {
            val middle = (low + high) ushr 1
            val index = middle * stride
            when {
                scalar < table[index] -> high = middle - 1
                scalar > table[index + 1] -> low = middle + 1
                else -> return index
            }
        }
        return -1
    }
